import{_ as e,C as i,o as d,c as p,a2 as t,E as n}from"./chunks/framework.CnJ-JtFX.js";const l="/lowcode-products-guide-site/diagrams/00-landscape.svg",u=JSON.parse('{"title":"第 00 章 · 低代码全景：五个工具箱，先选对再动手","description":"","frontmatter":{},"headers":[],"relativePath":"guide/00-lowcode-landscape.md","filePath":"guide/00-lowcode-landscape.md","lastUpdated":1792683644000}'),o={name:"guide/00-lowcode-landscape.md"};function h(r,a,c,k,m,g){const s=i("ComicFrame");return d(),p("div",null,[a[0]||(a[0]=t('<h1 id="第-00-章-·-低代码全景-五个工具箱-先选对再动手" tabindex="-1">第 00 章 · 低代码全景：五个工具箱，先选对再动手 <a class="header-anchor" href="#第-00-章-·-低代码全景-五个工具箱-先选对再动手" aria-label="Permalink to &quot;第 00 章 · 低代码全景：五个工具箱，先选对再动手&quot;">​</a></h1><blockquote class="meta"><p><strong>前置章节</strong>：无。这是整套教程的起点。<br><strong>所需环境</strong>：Node 22 LTS + pnpm 9.15.4，macOS / Linux / Windows（WSL2）均可。<br><strong>难度</strong>：★☆☆<br><strong>本章交付物</strong>：一张选型地图、一份 7 个 lab 的安装矩阵、一个能跑起来的文档站、一套统一的验收命令。</p></blockquote><p>欢迎来到这套低代码教程。接下来你会接触五个定位完全不同的产品，再加一个从零写起的教学级引擎。它们都能被叫作「低代码」，但解决的问题并不相同。本章不急着讲 API，而是先把地图铺开：低代码有哪些形态、每个形态对应什么产品、你的需求应该落在哪一格。</p><h2 id="本章你将获得" tabindex="-1">本章你将获得 <a class="header-anchor" href="#本章你将获得" aria-label="Permalink to &quot;本章你将获得&quot;">​</a></h2><p>读完本章，你应该能回答三个问题：</p><ol><li>面对一个「做个后台」的需求，如何判断该用 Schema 驱动、表单模型、编排引擎还是自由画布？</li><li>七个实验室分别验证什么能力，安装和启动命令是什么？</li><li>这套教程的两卷如何衔接：产品实战卷解决「怎么用」，进阶卷解决「怎么造」。</li></ol><p><a href="./../appendix/glossary">低代码</a>并不是一个产品品类，而是一组用配置、模型或可视化操作替代重复编码的手段。手段不同，适用边界就不同。把边界搞错，低代码就会从「提效工具」变成「维护负担」：页面看起来半天就搭完了，但改一个字段要翻三层配置，排查一个问题要同时理解产品协议和业务代码。</p><p>本章的选型地图会反复出现在后续章节里。每学完一个产品，你都应该回到这张地图，重新标注它的能力边界。选型不是一次性的拍板，而是随着团队能力、页面生命周期、交付节奏不断修正的判断。</p><h2 id="先看漫画" tabindex="-1">先看漫画 <a class="header-anchor" href="#先看漫画" aria-label="Permalink to &quot;先看漫画&quot;">​</a></h2>',9)),n(s,{ep:"EP.00",slug:"lowcode-landscape",title:"五个工具箱，先选对再动手"}),a[1]||(a[1]=t('<p>这一话讲了四个动作：先承认「拍脑袋选型」的代价，再按形态给工具分类，然后用四个问题缩小范围，最后强调「先跑通最小闭环」。漫画里的四个问题会在本章第三节展开，七个 lab 则会在第四节给出安装矩阵。</p><p>如果你只记住一句话：<strong>低代码选型的第一步不是比较功能列表，而是描述页面由谁维护、数据从哪里来、改动有多频繁。</strong></p><p>完整的逐格讲解在 <a href="./../comics/EP.00-lowcode-landscape">EP.00 漫画讲解</a>，包含四格对应的知识点、坑点清单和三道自测题。建议先看漫画建立直觉，再回到正文看细节。</p><h2 id="低代码全景与选型维度" tabindex="-1">低代码全景与选型维度 <a class="header-anchor" href="#低代码全景与选型维度" aria-label="Permalink to &quot;低代码全景与选型维度&quot;">​</a></h2><h3 id="五类形态-而不是五个产品" tabindex="-1">五类形态，而不是五个产品 <a class="header-anchor" href="#五类形态-而不是五个产品" aria-label="Permalink to &quot;五类形态，而不是五个产品&quot;">​</a></h3><p>行业里常把低代码当成一个赛道，但真正落地时，你面对的是五种不同的技术形态。它们的产物、扩展方式和失败模式都不一样。</p><table tabindex="0"><thead><tr><th>形态</th><th>核心产物</th><th>典型代表</th><th>最适合</th><th>主要代价</th></tr></thead><tbody><tr><td>Schema 驱动</td><td>一份 JSON 页面配置</td><td>amis</td><td>中后台 CRUD、运营后台</td><td>复杂交互要写自定义组件</td></tr><tr><td>表单领域模型</td><td>字段树 + 响应式规则</td><td>Formily</td><td>复杂表单、联动、异步校验</td><td>页面层与数据层要自己组装</td></tr><tr><td>可视化编排引擎</td><td>设计器 + 渲染器 + 物料协议</td><td>lowcode-engine</td><td>平台型产品、长期演进的搭建系统</td><td>概念多、接入与治理成本高</td></tr><tr><td>页面搭建器</td><td>编辑器 + 运行时 + 数据源</td><td>tmagic-editor</td><td>运营页面、活动页、内容页</td><td>偏页面生产，复杂业务逻辑弱</td></tr><tr><td>自由画布</td><td>HTML/CSS 结构 + 样式</td><td>GrapesJS</td><td>视觉自由、静态页面、邮件模板</td><td>工程约束弱，需要自建规范</td></tr></tbody></table><p>这张表不是功能对比，而是「产物形态」对比。amis 的产物是一棵 JSON Schema 树，Formily 的产物是字段模型，lowcode-engine 的产物是带物料协议的节点树，tmagic-editor 的产物是可被运行时解释的页面 Schema，GrapesJS 的产物更接近真实 DOM 与 CSS。</p><p>产物形态决定了三件事：谁来维护、如何 diff、如何回滚。JSON 配置容易做版本管理和灰度；DOM/CSS 产物更自由，但结构约束弱；字段模型擅长表达联动，却不负责页面布局。选型时先看产物，再看功能，能避免很多「 demo 很惊艳、上线很痛苦」的误判。</p><p><img src="'+l+`" alt="低代码五类形态与代表产品"></p><h3 id="产品矩阵-五个主线-两个对照" tabindex="-1">产品矩阵：五个主线 + 两个对照 <a class="header-anchor" href="#产品矩阵-五个主线-两个对照" aria-label="Permalink to &quot;产品矩阵：五个主线 + 两个对照&quot;">​</a></h3><p>本教程的主线是五个产品，另有两个平台型产品只做对照，不进入安装链路。</p><table tabindex="0"><thead><tr><th>产品</th><th>定位</th><th>技术栈</th><th>教程章节</th><th>是否做 lab</th></tr></thead><tbody><tr><td>amis</td><td>Schema 驱动中后台</td><td>React 18</td><td>01~03</td><td>是</td></tr><tr><td>Formily</td><td>表单领域模型</td><td>React 18 + antd 5</td><td>04~06</td><td>是</td></tr><tr><td>lowcode-engine</td><td>可视化编排内核</td><td>React（跟随官方 demo）</td><td>07~09</td><td>是</td></tr><tr><td>tmagic-editor</td><td>页面搭建器</td><td>Vue 3</td><td>10~11</td><td>是</td></tr><tr><td>GrapesJS</td><td>自由画布</td><td>原生 TypeScript</td><td>12~13</td><td>是</td></tr><tr><td>Appsmith</td><td>平台型应用搭建</td><td>自带后端 + Docker</td><td>14（对照）</td><td>否</td></tr><tr><td>ToolJet</td><td>平台型应用搭建</td><td>自带后端 + Docker</td><td>14（对照）</td><td>否</td></tr></tbody></table><p>为什么把 Appsmith 和 ToolJet 放在对照位？因为它们不是「前端库」，而是「平台」：自带后端、数据库连接、账号体系，安装形态是 Docker 服务。把它们塞进主线 lab，会让读者误以为低代码的前端选型必须绑定某个后端平台。第 14 章会解释它们的适用场景和代价，但本教程的安装链路只覆盖纯前端可验证的部分。</p><h3 id="选型四问" tabindex="-1">选型四问 <a class="header-anchor" href="#选型四问" aria-label="Permalink to &quot;选型四问&quot;">​</a></h3><p>把功能列表收起来，先回答四个问题。它们分别对应「结构稳定性、表单复杂度、编排需求、布局自由度」。</p><p><strong>第一问：页面结构稳定、以 CRUD 为主吗？</strong> 如果答案是「是」，优先考虑 amis。列表、表单、弹窗、筛选、分页这些中后台高频结构，amis 已经用 Schema 封装好了。你付出的代价是学习它的配置协议；换来的是极低的页面搭建成本。</p><p><strong>第二问：表单联动与校验是核心难点吗？</strong> 如果页面主体是表单，且联动关系复杂（省市区、额度计算、异步唯一性校验、动态增减行），Formily 的字段模型比任何「配置页面」都更可靠。它把字段当成一等公民，联动写在模型层，测试和复用都更容易。</p><p><strong>第三问：需要让非开发者长期搭建页面吗？</strong> 这时候才轮到 lowcode-engine 或 tmagic-editor。两者都提供设计器，但侧重点不同：lowcode-engine 更像平台底座，强调物料、插件、出码与扩展；tmagic-editor 更像页面生产工具，强调编辑器与运行时分离、数据源、事件和动画。</p><p><strong>第四问：需要像素级自由布局并导出 HTML/CSS 吗？</strong> 如果产物要脱离框架运行，或者视觉还原度是第一位，GrapesJS 更合适。它的画布直接操作 DOM，自由度高，但工程约束需要团队自己补。</p><p>四个问题没有标准答案，但它们能帮你排除掉明显不合适的选项。选型的目标不是找到「最强」的产品，而是找到「代价可接受」的产品。</p><h3 id="两卷路线-先用-再造" tabindex="-1">两卷路线：先用，再造 <a class="header-anchor" href="#两卷路线-先用-再造" aria-label="Permalink to &quot;两卷路线：先用，再造&quot;">​</a></h3><p>这套教程分两卷，顺序固定。</p><p>产品实战卷（第 00~15 章）按产品逐个上手：先跑通最小示例，再理解核心协议，最后做一个可验收的页面或扩展。学完这一卷，你应该能为一个真实需求完成选型，并搭出可运行的原型。</p><p>从零搭建进阶卷（第 16~20 章）从空目录开始，写一个教学级 mini 低代码系统：Schema 协议、递归渲染器、可视化设计器、撤销重做与插件、出码导出。学完这一卷，你应该能解释商业产品的内核链路，而不是只会调用 API。</p><p>两卷共用同一套漫画、文档门禁和部署链路。进阶卷不依赖任何商业低代码产品包，只依赖 Vue 3、Vite、TypeScript、Vitest、zod 和 jsep。它不会宣称生产可用，也不会和商业产品做功能对等比较；它的价值是「把黑盒拆开给你看」。</p><h2 id="环境准备与跑通仓库" tabindex="-1">环境准备与跑通仓库 <a class="header-anchor" href="#环境准备与跑通仓库" aria-label="Permalink to &quot;环境准备与跑通仓库&quot;">​</a></h2><h3 id="固定版本-不要追新" tabindex="-1">固定版本，不要追新 <a class="header-anchor" href="#固定版本-不要追新" aria-label="Permalink to &quot;固定版本，不要追新&quot;">​</a></h3><p>整套教程固定两个版本：Node 22 LTS 与 pnpm 9.15.4。原因很现实：lockfile 格式、依赖解析、CI 缓存行为都跟主版本绑定。用 Node 24 配 pnpm 12 生成 lockfile，再拿到 CI 的 Node 22 + pnpm 9 上跑 <code>--frozen-lockfile</code>，最常见的结局就是安装失败或依赖树漂移。</p><p>先确认版本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 期望 v22.x</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 期望 9.15.4</span></span></code></pre></div><p>如果本机装了多个 Node 版本，用 nvm 切换；如果 pnpm 版本不对，用 corepack 激活固定版本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nvm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nvm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepare</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm@9.15.4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --activate</span></span></code></pre></div><p>不要用 <code>npm install -g pnpm</code> 追最新版。全局安装会把版本绑死在本机，换一台机器或进 CI 又要重来；<code>packageManager</code> 字段加 corepack 才是可复现的做法。</p><h3 id="文档站-三条命令" tabindex="-1">文档站：三条命令 <a class="header-anchor" href="#文档站-三条命令" aria-label="Permalink to &quot;文档站：三条命令&quot;">​</a></h3><p>项目根只负责文档站与校验脚本，不管理 labs 的依赖。首次运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><p>浏览器打开终端输出的地址（默认 <code>http://localhost:5173</code>），应能看到首页。构建与本地预览：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span></span></code></pre></div><p>构建产物在 <code>.vitepress/dist</code>。部署到 GitHub Pages 时，CI 会注入 <code>DEPLOY_BASE</code>，把资源前缀改成 <code>/&lt;仓库名&gt;/</code>；本地开发不需要设置这个变量。</p><h3 id="七个-lab-的安装矩阵" tabindex="-1">七个 lab 的安装矩阵 <a class="header-anchor" href="#七个-lab-的安装矩阵" aria-label="Permalink to &quot;七个 lab 的安装矩阵&quot;">​</a></h3><p>七个 lab 是独立工程，各自有 <code>package.json</code> 和 <code>pnpm-lock.yaml</code>，不共享 <code>node_modules</code>，也不在根目录建 workspace。这样做的好处是 React 18/19、antd 4/5、Vue 3 的版本不会互相污染；代价是要多敲几次 <code>cd</code>。</p><table tabindex="0"><thead><tr><th>lab</th><th>技术栈</th><th>章节目录</th><th>建议端口</th><th>启动命令</th></tr></thead><tbody><tr><td>amis</td><td>React 18 + Vite</td><td>01 / 02 / 03</td><td>5174</td><td><code>cd labs/amis &amp;&amp; pnpm install &amp;&amp; pnpm dev</code></td></tr><tr><td>formily</td><td>React 18 + antd 5 + Vite</td><td>04 / 05 / 06</td><td>5175</td><td><code>cd labs/formily &amp;&amp; pnpm install &amp;&amp; pnpm dev</code></td></tr><tr><td>lowcode-engine</td><td>React + 官方 demo 构建链</td><td>07 / 08 / 09</td><td>5176</td><td><code>cd labs/lowcode-engine &amp;&amp; pnpm install &amp;&amp; pnpm dev</code></td></tr><tr><td>tmagic-editor</td><td>Vue 3 + Vite</td><td>10 / 11</td><td>5177</td><td><code>cd labs/tmagic-editor &amp;&amp; pnpm install &amp;&amp; pnpm dev</code></td></tr><tr><td>grapesjs</td><td>原生 TypeScript + Vite</td><td>12 / 13</td><td>5178</td><td><code>cd labs/grapesjs &amp;&amp; pnpm install &amp;&amp; pnpm dev</code></td></tr><tr><td>capstone</td><td>React 18 + amis + Formily</td><td>15</td><td>5179</td><td><code>cd labs/capstone &amp;&amp; pnpm install &amp;&amp; pnpm dev</code></td></tr><tr><td>mini-lowcode</td><td>Vue 3 + Vite + Vitest</td><td>16~20</td><td>5180</td><td><code>cd labs/mini-lowcode &amp;&amp; pnpm install &amp;&amp; pnpm dev</code></td></tr></tbody></table><p>端口只是约定。Vite 发现端口被占用会自动顺延，以终端实际输出为准。所有 lab 的端口都会回填到 <a href="./../appendix/commands">命令速查</a>，方便你对照。</p><p>每个 lab 的根页面都列出章节目录、验收点和当前版本。进入 lab 后先看根页面，再点进具体章节，不要直接猜路由。</p><h3 id="一套验收命令" tabindex="-1">一套验收命令 <a class="header-anchor" href="#一套验收命令" aria-label="Permalink to &quot;一套验收命令&quot;">​</a></h3><p>项目根提供统一门禁：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>它会依次执行环境检查、漫画校验、内容校验、链接校验、lab 结构校验和格式检查。任何一项失败都会返回非零退出码。CI 与本地使用同一条命令，避免「本地过了、CI 挂了」。</p><p>产品 lab 的安装、构建和烟测由另一个脚本在本地执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/smoke-labs.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span></code></pre></div><p>这个脚本不进 CI，因为它要安装七个工程，耗时且依赖网络。CI 只安装根工程，保证文档门禁和部署稳定。</p><h3 id="本章的最小验收" tabindex="-1">本章的最小验收 <a class="header-anchor" href="#本章的最小验收" aria-label="Permalink to &quot;本章的最小验收&quot;">​</a></h3><p>完成环境准备后，你应该能独立完成下面三步，且每一步都有可见输出：</p><ol><li><code>pnpm docs:dev</code> 启动成功，首页、教程侧边栏、搜索框都可用；</li><li><code>node scripts/check-env.mjs</code> 输出 Node、pnpm、七个 lab 目录和文档依赖全部通过；</li><li>任选一个已完成的 lab，按矩阵中的命令启动，根页面能进入对应章节。</li></ol><p>如果第三步还做不到，不要急着往下读。先记录报错原文，对照下一节的「跑不起来？」逐条排查。低代码教程最容易出现的问题不是概念难，而是环境版本不对导致示例跑不起来。</p><h2 id="跑不起来" tabindex="-1">跑不起来？ <a class="header-anchor" href="#跑不起来" aria-label="Permalink to &quot;跑不起来？&quot;">​</a></h2><h3 id="报错一-err-pnpm-unsupported-engine-或-lockfile-版本不兼容" tabindex="-1">报错一：<code>ERR_PNPM_UNSUPPORTED_ENGINE</code> 或 lockfile 版本不兼容 <a class="header-anchor" href="#报错一-err-pnpm-unsupported-engine-或-lockfile-版本不兼容" aria-label="Permalink to &quot;报错一：\`ERR_PNPM_UNSUPPORTED_ENGINE\` 或 lockfile 版本不兼容&quot;">​</a></h3><p><strong>现象</strong>：执行 <code>pnpm install --frozen-lockfile</code> 时报锁文件版本不支持，或者提示当前 Node 版本不满足 engines。</p><p><strong>原因</strong>：本机 Node 低于 22，或 pnpm 主版本不是 9。lockfile 的 <code>lockfileVersion</code> 与 pnpm 主版本绑定，跨主版本会直接拒绝安装。</p><p><strong>修复</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nvm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nvm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepare</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm@9.15.4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>如果是在 lab 目录里报错，先确认你进对了目录。每个 lab 都有自己的 lockfile，根目录的 lockfile 不能替代。</p><h3 id="报错二-cannot-find-module-vitepress" tabindex="-1">报错二：<code>Cannot find module &#39;vitepress&#39;</code> <a class="header-anchor" href="#报错二-cannot-find-module-vitepress" aria-label="Permalink to &quot;报错二：\`Cannot find module &#39;vitepress&#39;\`&quot;">​</a></h3><p><strong>现象</strong>：<code>pnpm docs:dev</code> 直接报模块找不到，或提示 <code>.vitepress/config.ts</code> 加载失败。</p><p><strong>原因</strong>：根工程依赖没有安装，或 <code>node_modules</code> 被清理过。也可能是在 lab 目录里执行了根命令。</p><p><strong>修复</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lowcode-products-guide</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><p>确认当前目录有 <code>package.json</code> 且其中包含 <code>vitepress</code>。如果刚切换过 Node 版本，重新执行一次 <code>pnpm install</code>，避免原生依赖与 Node ABI 不匹配。</p><h3 id="报错三-文档站能构建-但页面白屏" tabindex="-1">报错三：文档站能构建，但页面白屏 <a class="header-anchor" href="#报错三-文档站能构建-但页面白屏" aria-label="Permalink to &quot;报错三：文档站能构建，但页面白屏&quot;">​</a></h3><p><strong>现象</strong>：<code>pnpm docs:build</code> 成功，浏览器打开却是空白；控制台可能没有任何报错。</p><p><strong>原因</strong>：Markdown 里出现了未被反引号包裹的裸花括号，例如直接写 <code>{ name: &quot;amis&quot; }</code>。VitePress 底层的 Markdown 插件会把它当成 HTML 属性解析，SSR 阶段不报错，客户端 hydration 失败后白屏。</p><p><strong>修复</strong>：把所有代码片段放进行内反引号或围栏代码块：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">配置里写 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`{ &quot;type&quot;: &quot;page&quot; }\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">，不要裸写花括号。</span></span></code></pre></div><p>同理，正文里的 <code>localhost</code> 地址也要包进反引号，否则链接检查器会把它当成外链或死链。改完后重新构建，并用浏览器强刷一次。</p><h3 id="报错四-端口被占用" tabindex="-1">报错四：端口被占用 <a class="header-anchor" href="#报错四-端口被占用" aria-label="Permalink to &quot;报错四：端口被占用&quot;">​</a></h3><p><strong>现象</strong>：<code>pnpm dev</code> 提示端口已在使用，或者启动后访问的是另一个项目。</p><p><strong>原因</strong>：默认端口被其他进程占用，Vite 自动顺延到了新端口，但你还开着旧地址。</p><p><strong>修复</strong>：看终端输出里的实际端口，或者显式指定：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5181</span></span></code></pre></div><p>不要直接杀掉不认识的进程。先确认占用者是不是你正在跑的其他 lab，再决定换端口还是关进程。</p><h2 id="避坑清单" tabindex="-1">避坑清单 <a class="header-anchor" href="#避坑清单" aria-label="Permalink to &quot;避坑清单&quot;">​</a></h2><ol><li><strong>不要建根级 <code>pnpm-workspace.yaml</code>。</strong> 七个 lab 一旦被提升到同一个 workspace，React 18/19、antd 4/5、Vue 3 的依赖会互相污染，而且 lockfile 变动会让 CI 的 <code>--frozen-lockfile</code> 频繁失败。根工程只管理文档与校验脚本。</li><li><strong>不要把 <code>latest</code> 或 <code>^</code> 写进产品核心包。</strong> 低代码产品的 API 跨版本变化很大，博客里的写法往往对应旧版本。所有核心包使用精确版本，安装用 <code>pnpm add --save-exact</code>，实际版本回填 <a href="./../appendix/versions">版本锁定表</a>。</li><li><strong>不要一上来就装七个 lab。</strong> 按产品推进，跑通一个再下一个。一次性装完再集中排错，会把版本问题、网络问题、配置问题混在一起，定位成本成倍增加。</li><li><strong>不要把 <code>labs/</code> 放进文档站的扫描范围。</strong> VitePress 的 <code>srcExclude</code> 已排除 <code>labs/**</code>、<code>scripts/**</code> 和根 <code>README.md</code>；如果你自己改配置，记得保留这三项，否则 lab README 的相对链接触发构建失败。</li><li><strong>不要手写锚点 slug。</strong> 中文标题生成锚点时会做小写、去标点、重复标题加序号等处理。优先链接到页面，需要锚点时用 <code>./xx.md#标题</code> 并跑 <code>check-links.mjs</code> 验证。</li><li><strong>不要伪造「已跑通」。</strong> 本教程所有结论都应该能用命令或截图复现。装不上就说装不上，构建失败就贴报错；把失败步骤标成完成，比不会更糟。</li></ol><h2 id="小结与自测" tabindex="-1">小结与自测 <a class="header-anchor" href="#小结与自测" aria-label="Permalink to &quot;小结与自测&quot;">​</a></h2><p>本章的核心不是记住五个产品的功能，而是建立「形态 → 产物 → 代价」的判断链：</p><ul><li>低代码有五类形态：Schema 驱动、表单模型、编排引擎、页面搭建器、自由画布；</li><li>选型先问四个问题：结构是否稳定、表单是否复杂、是否需要非开发者编排、是否需要像素级自由布局；</li><li>产品实战卷解决「怎么用」，进阶卷解决「怎么造」；</li><li>环境固定 Node 22 + pnpm 9.15.4，七个 lab 独立安装，根工程只做文档与门禁。</li></ul><details><summary><b>1. 为什么不能把七个 lab 放进同一个 pnpm workspace？</b></summary><p>因为它们的运行时和技术栈不同：amis/Formily 要 React 18，tmagic-editor 要 Vue 3，lowcode-engine 跟随官方 demo 的 React 版本，GrapesJS 是原生 TypeScript。workspace 会把依赖提升到根 <code>node_modules</code>，版本冲突时只能靠 overrides 打补丁，lockfile 也会互相影响。独立工程虽然多几次安装，但边界清晰、可独立构建、CI 也不必安装全部 lab。</p></details><details><summary><b>2. 一个「客户运营后台」，页面以列表和表单为主，偶尔有复杂联动，应该怎么选？</b></summary><p>先用 amis 搭页面骨架：列表、筛选、弹窗、CRUD 都能用 Schema 快速完成。把最复杂的表单（例如带异步校验和动态字段的那一块）单独用 Formily 实现，再嵌进 amis 页面。这样页面层享受配置效率，表单层保留模型能力。只有当需求真的需要非开发者长期拖拽编排时，才考虑 lowcode-engine 或 tmagic-editor；为「偶尔改一次」引入完整设计器，维护成本通常不划算。</p></details><details><summary><b>3. 为什么教程要求先跑通最小示例，再读原理？</b></summary><p>低代码产品的概念密度很高，纯读文档很容易把「协议」「物料」「渲染器」当成抽象名词。先跑通一个最小示例，你能看到输入（Schema/配置）与输出（页面/DOM）的真实对应关系，再回读原理时，每个概念都有落点。更重要的是，跑通过程会暴露版本、样式、入口等真实问题，这些问题才是日常使用的主要成本。</p></details><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>下一章进入 amis。你会先用一份 JSON Schema 渲染出一个页面，再把它扩展成带筛选、分页和弹窗的 CRUD。开始前先完成三项检查：</p><ol><li><code>node -v</code> 是 22.x，<code>pnpm -v</code> 是 9.15.4；</li><li>根目录 <code>pnpm docs:dev</code> 能启动，侧边栏能看到第 01 章；</li><li>进入 <code>labs/amis</code>，按 README 安装依赖并启动，根页面能打开。</li></ol><p>如果暂时不想装 lab，也可以先读第 01 章正文和漫画，理解 amis 的 Schema 结构，再回来动手。但请不要跳过「跑不起来？」小节：amis 的样式资源和 React 版本是最常见的两个坑。</p><p>继续阅读：<a href="./01-amis-quickstart">第 01 章 · amis 快速上手</a>。</p>`,94))])}const F=e(o,[["render",h]]);export{u as __pageData,F as default};
